{
 "path": "/home/USER/continual-arc-baselines/.workbench/stage1/HPL0-hermes-luna6-high-fresh0/frozen/held-out-reference/play/users/u069/system/state/workspace/programs/task-d3cac0bd.py",
 "content": "def transform(grid):
    """Connect matching non-background tile symbols across blank gutters."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])

    def bands(n, occupied):
        result = []
        start = None
        for i in range(n + 1):
            on = i < n and occupied(i)
            if on and start is None:
                start = i
            elif not on and start is not None:
                result.append((start, i - 1))
                start = None
        return result

    rb = bands(h, lambda r: any(grid[r][c] != 0 for c in range(w)))
    cb = bands(w, lambda c: any(grid[r][c] != 0 for r in range(h)))
    rb = [b for b in rb if b[1] - b[0] >= 2]
    cb = [b for b in cb if b[1] - b[0] >= 2]
    if not rb or not cb:
        return out
    rcent = [(a + b) // 2 for a, b in rb]
    ccent = [(a + b) // 2 for a, b in cb]
    cells = [[grid[r][c] for c in ccent] for r in rcent]
    from collections import Counter
    neutral = Counter(v for row in cells for v in row).most_common(1)[0][0]

    # Connect same-color symbols when all intervening tiles are neutral.
    for i, row in enumerate(cells):
        for left in range(len(ccent)):
            color = row[left]
            if color == neutral:
                continue
            for right in range(left + 1, len(ccent)):
                if row[right] != color:
                    continue
                if all(row[k] == neutral for k in range(left + 1, right)):
                    r0, r1 = rb[i]
                    for c in range(left, right):
                        gap_start = cb[c][1] + 1
                        gap_end = cb[c + 1][0] - 1
                        for r in range(r0 + 1, r1):
                            for x in range(gap_start, gap_end + 1):
                                if grid[r][x] == 0:
                                    out[r][x] = color

    for j in range(len(ccent)):
        col = [cells[i][j] for i in range(len(rcent))]
        for top in range(len(rcent)):
            color = col[top]
            if color == neutral:
                continue
            for bottom in range(top + 1, len(rcent)):
                if col[bottom] != color:
                    continue
                if all(col[k] == neutral for k in range(top + 1, bottom)):
                    c0, c1 = cb[j]
                    for r in range(top, bottom):
                        gap_start = rb[r][1] + 1
                        gap_end = rb[r + 1][0] - 1
                        for y in range(gap_start, gap_end + 1):
                            for c in range(c0 + 1, c1):
                                if grid[y][c] == 0:
                                    out[y][c] = color
    return out
