 "content": "def transform(grid):
    """Extend repeated colored markers through intervening neutral tiles."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])

    def bands(n, occupied):
        found = []
        start = None
        for i in range(n + 1):
            on = i < n and occupied(i)
            if on and start is None:
                start = i
            elif not on and start is not None:
                found.append((start, i - 1))
                start = None
        return found

    rb = bands(h, lambda r: any(grid[r][c] for c in range(w)))
    cb = bands(w, lambda c: any(grid[r][c] for r in range(h)))
    rb = [b for b in rb if b[1] - b[0] >= 2]
    cb = [b for b in cb if b[1] - b[0] >= 2]
    if not rb or not cb:
        return out

    rcent = [a + (b - a + 1) // 2 for a, b in rb]
    ccent = [a + (b - a + 1) // 2 for a, b in cb]
    cells = [[grid[r][c] for c in ccent] for r in rcent]
    from collections import Counter
    neutral = Counter(v for row in cells for v in row).most_common(1)[0][0]

    # In each row, match separated occurrences; connect only center portions
    # whose endpoints contain those same colors.
    for i, row in enumerate(cells):
        for left in range(len(ccent)):
            color = row[left]
            if color == neutral:
                continue
            for right in range(left + 1, len(ccent)):
                if row[right] != color:
                    continue
                if any(row[k] != neutral for k in range(left + 1, right)):
                    continue
                # Duplicated adjacent markers with a farther repetition form a
                # cluster; only their extended side should be connected.
                if right == left + 1 and any(
                    row[q] == color for q in range(len(ccent))
                    if q != left and q != right
                ):
                    continue
                rows = [r for r in range(rb[i][0], rb[i][1] + 1)
                        if grid[r][ccent[left]] == color and grid[r][ccent[right]] == color]
                for c in range(left, right):
                    x0, x1 = cb[c][1] + 1, cb[c + 1][0] - 1
                    for r in rows:
                        for x in range(x0, x1 + 1):
                            if grid[r][x] == 0:
                                out[r][x] = color

    # Same vertically, using the rows' inner/center columns as the marker axis.
    for j in range(len(ccent)):
        col = [cells[i][j] for i in range(len(rcent))]
        for top in range(len(rcent)):
            color = col[top]
            if color == neutral:
                continue
            for bottom in range(top + 1, len(rcent)):
                if col[bottom] != color:
                    continue
                if any(col[k] != neutral for k in range(top + 1, bottom)):
                    continue
                cols = [c for c in range(cb[j][0], cb[j][1] + 1)
                        if grid[rcent[top]][c] == color and grid[rcent[bottom]][c] == color]
                for r in range(top, bottom):
                    y0, y1 = rb[r][1] + 1, rb[r + 1][0] - 1
                    for c in cols:
                        for y in range(y0, y1 + 1):
                            if grid[y][c] == 0:
                                out[y][c] = color
    return out
