    """Join aligned matching interior colors across blank tile gutters."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    def bands(n, occupied):
        result = []
        start = None
        for i in range(n + 1):
            on = i < n and occupied(i)
            if on and start is None:
                start = i
            elif not on and start is not None:
                result.append((start, i - 1))
                start = None
        return result

    row_bands = [b for b in bands(h, lambda r: any(grid[r][c] != 0 for c in range(w)))
                  if b[1] - b[0] >= 2]
    col_bands = [b for b in bands(w, lambda c: any(grid[r][c] != 0 for r in range(h)))
                  if b[1] - b[0] >= 2]
    if len(row_bands) < 2 or len(col_bands) < 2:
        return out

    # Infer each tile's background from its outer border (the repeated frame color).
    from collections import Counter
    border_colors = Counter()
    for r0, r1 in row_bands:
        for c0, c1 in col_bands:
            for r in range(r0, r1 + 1):
                for c in range(c0, c1 + 1):
                    if r in (r0, r1) or c in (c0, c1):
                        if grid[r][c] != 0:
                            border_colors[grid[r][c]] += 1
    if not border_colors:
        return out
    background = border_colors.most_common(1)[0][0]

    # Only compare tiles of the common dimensions; clipped edge bands are frames,
    # not complete tile contents.
    rh = Counter(r1 - r0 + 1 for r0, r1 in row_bands).most_common(1)[0][0]
    cw = Counter(c1 - c0 + 1 for c0, c1 in col_bands).most_common(1)[0][0]
    row_bands = [b for b in row_bands if b[1] - b[0] + 1 == rh]
    col_bands = [b for b in col_bands if b[1] - b[0] + 1 == cw]
    if len(row_bands) < 2 or len(col_bands) < 2:
        return out

    nr, nc = len(row_bands), len(col_bands)

    # For every tile row, connect aligned same-color pixels in repeated objects
    # when all intermediate tile pixels at that offset are background.
    for ti, (r0, r1) in enumerate(row_bands):
        for left in range(nc):
            c0, c1 = col_bands[left]
            for right in range(left + 1, nc):
                d0, d1 = col_bands[right]
                for dy in range(1, rh - 1):
                    for dx in range(1, cw - 1):
                        color = grid[r0 + dy][c0 + dx]
                        if color in (0, background) or grid[r0 + dy][d0 + dx] != color:
