                            continue
                        rr = r0 + dy
                        for k in range(left, right):
                            x0, x1 = col_bands[k][1] + 1, col_bands[k + 1][0] - 1
                            for x in range(x0, x1 + 1):
                                if grid[rr][x] == 0:
                                    out[rr][x] = color

