    for tj in range(nc):
        c0, c1 = col_bands[tj]
        for top in range(nr):
            r0, r1 = row_bands[top]
            for bottom in range(top + 1, nr):
                d0, d1 = row_bands[bottom]
                for dy in range(1, rh - 1):
                    for dx in range(1, cw - 1):
                        color = grid[r0 + dy][c0 + dx]
                        if color in (0, background) or grid[d0 + dy][c0 + dx] != color:
                            continue
                        if any(grid[row_bands[k][0] + dy][c0 + dx] != background
