    rb = runs(h, lambda r: any(grid[r][c] for c in range(w)))
    cb = runs(w, lambda c: any(grid[r][c] for r in range(h)))
    rb = [b for b in rb if b[1] - b[0] >= 2]
    cb = [b for b in cb if b[1] - b[0] >= 2]
    if not rb or not cb:
        return out

    rh = Counter(b[1] - b[0] + 1 for b in rb).most_common(1)[0][0]
    cw = Counter(b[1] - b[0] + 1 for b in cb).most_common(1)[0][0]
    # The final bands can be cropped at the grid edge; retain complete tiles.
    rb = [b for b in rb if b[1] - b[0] + 1 == rh]
    cb = [b for b in cb if b[1] - b[0] + 1 == cw]
    if len(rb) < 2 or len(cb) < 2:
        return out

    border_counts = Counter()
    for r0, r1 in rb:
        for c0, c1 in cb:
            for r in range(r0, r1 + 1):
                for c in range(c0, c1 + 1):
                    if r in (r0, r1) or c in (c0, c1):
                        if grid[r][c]:
                            border_counts[grid[r][c]] += 1
    if not border_counts:
        return out
    frame = border_counts.most_common(1)[0][0]

    nr, nc = len(rb), len(cb)
    # Look at each interior offset. A color present in two or more tiles in
    # the same tile-row/column is carried through the blank gutter between them.
    for ti, (r0, r1) in enumerate(rb):
        for dy in range(1, rh - 1):
            for dx in range(1, cw - 1):
                vals = [grid[r0 + dy][c0 + dx] for c0, _ in cb]
                for a in range(nc):
                    color = vals[a]
                    if color in (0, frame):
