    def runs(n, pred):
        ans, start = [], None
        for i in range(n + 1):
            active = i < n and pred(i)
            if active and start is None:
                start = i
            elif not active and start is not None:
                ans.append((start, i - 1))
                start = None
        return ans

    rb = runs(h, lambda r: any(grid[r][c] != 0 for c in range(w)))
    cb = runs(w, lambda c: any(grid[r][c] != 0 for r in range(h)))
    rb = [x for x in rb if x[1] - x[0] >= 2]
    cb = [x for x in cb if x[1] - x[0] >= 2]
    if not rb or not cb:
        return out

    # A clipped run at an edge is still a real tile; keep the full-sized interior
    # tile dimensions inferred from the mode, but retain the clipped bands too.
    rh = Counter(b - a + 1 for a, b in rb).most_common(1)[0][0]
    cw = Counter(b - a + 1 for a, b in cb).most_common(1)[0][0]
    frames = Counter()
    for r0, r1 in rb:
        for c0, c1 in cb:
            for r in range(r0, r1 + 1):
                for c in range(c0, c1 + 1):
                    if r in (r0, r1) or c in (c0, c1):
                        if grid[r][c]:
                            frames[grid[r][c]] += 1
    frame = frames.most_common(1)[0][0] if frames else 0

