            for dx in range(1, cw - 1):
                vals = [grid[r0 + dy][c0 + dx] if c0 + dx <= c1 else 0
                        for c0, c1 in cb]
                for a, color in enumerate(vals):
                    if color in (0, frame):
                        continue
                    for b in range(a + 1, len(cb)):
                        if vals[b] != color:
                            continue
                        if any(vals[k] not in (0, frame) for k in range(a + 1, b)):
                            continue
                        for k in range(a, b):
                            x0, x1 = cb[k][1] + 1, cb[k + 1][0] - 1
                            rr = r0 + dy
                            for x in range(x0, x1 + 1):
