 "content": "def transform(grid):
    """Join aligned, repeated interior colors through gaps between framed tiles."""
    from collections import Counter
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    def runs(n, occupied):
        result = []
        start = None
        for i in range(n + 1):
            on = i < n and occupied(i)
            if on and start is None:
                start = i
            elif not on and start is not None:
                result.append((start, i - 1))
                start = None
        return result

    rb = runs(h, lambda r: any(grid[r][c] for c in range(w)))
    cb = runs(w, lambda c: any(grid[r][c] for r in range(h)))
    rb = [b for b in rb if b[1] - b[0] >= 2]
    cb = [b for b in cb if b[1] - b[0] >= 2]
    if not rb or not cb:
        return out

    rh = Counter(b[1] - b[0] + 1 for b in rb).most_common(1)[0][0]
    cw = Counter(b[1] - b[0] + 1 for b in cb).most_common(1)[0][0]
    frame = Counter(v for row in grid for v in row if v != 0).most_common(1)[0][0]

    # Inspect all offsets, including boundary pixels of the tile interiors: the
    # grid consists of little framed panels whose colored centers can be 2x2.
    for ri, (r0, r1) in enumerate(rb):
        for dy in range(rh):
            if r0 + dy > r1:
                continue
            for dx in range(cw):
                vals = [grid[r0 + dy][c0 + dx] if c0 + dx <= c1 else 0
                        for c0, c1 in cb]
                for a, color in enumerate(vals):
                    if color in (0, frame):
                        continue
                    for b in range(a + 1, len(cb)):
                        if vals[b] != color:
                            continue
                        if any(vals[k] not in (0, frame) for k in range(a + 1, b)):
                            continue
                        for k in range(a, b):
                            x0, x1 = cb[k][1] + 1, cb[k + 1][0] - 1
                            rr = r0 + dy
                            for x in range(x0, x1 + 1):
                                if grid[rr][x] == 0:
                                    out[rr][x] = color

    for ci, (c0, c1) in enumerate(cb):
        for dy in range(rh):
            for dx in range(cw):
                if c0 + dx > c1:
                    continue
                vals = [grid[r0 + dy][c0 + dx] if r0 + dy <= r1 else 0
                        for r0, r1 in rb]
                for a, color in enumerate(vals):
                    if color in (0, frame):
                        continue
                    for b in range(a + 1, len(rb)):
                        if vals[b] != color:
                            continue
                        if any(vals[k] not in (0, frame) for k in range(a + 1, b)):
                            continue
                        for k in range(a, b):
                            y0, y1 = rb[k][1] + 1, rb[k + 1][0] - 1
                            cc = c0 + dx
                            for y in range(y0, y1 + 1):
                                if grid[y][cc] == 0:
                                    out[y][cc] = color
    return out
