 "content": "def transform(grid):
    """Extend repeated inner colors horizontally and vertically across gutters."""
    from collections import Counter
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    def runs(n, filled):
        found, start = [], None
        for i in range(n + 1):
            on = i < n and filled(i)
            if on and start is None:
                start = i
            elif not on and start is not None:
                found.append((start, i - 1))
                start = None
        return found

    rb = runs(h, lambda r: any(grid[r][c] for c in range(w)))
    cb = runs(w, lambda c: any(grid[r][c] for r in range(h)))
    rb = [b for b in rb if b[1] - b[0] >= 2]
    cb = [b for b in cb if b[1] - b[0] >= 2]
    if not rb or not cb:
        return out

    # Tile center locations (including clipped tiles at grid edges).
    rpos = [a + (b - a + 1) // 2 for a, b in rb]
    cpos = [a + (b - a + 1) // 2 for a, b in cb]
    marks = [[grid[r][c] for c in cpos] for r in rpos]
    # Most common nonzero tile-center color is the neutral/base fill.
    neutral = Counter(v for row in marks for v in row if v != 0).most_common(1)[0][0]

    # Match same-color marks across a run of neutral marks. Every inner pixel in
    # the tile's symbol is extended; gutters span between the neighboring frames.
    for i, row in enumerate(marks):
        r0, r1 = rb[i]
        for a in range(len(cpos)):
            color = row[a]
            if color == neutral or color == 0:
                continue
            for b in range(a + 1, len(cpos)):
                if row[b] != color:
                    continue
                if any(row[k] not in (neutral, 0) for k in range(a + 1, b)):
                    continue
                # Entire tile-interior vertical extent, matching the object's rows.
                for rr in range(r0 + 1, r1):
                    if grid[rr][cpos[a]] != color or grid[rr][cpos[b]] != color:
                        continue
                    for k in range(a, b):
                        for x in range(cb[k][1] + 1, cb[k + 1][0]):
                            if grid[rr][x] == 0:
                                out[rr][x] = color

    for j, c in enumerate(cpos):
        col = [marks[i][j] for i in range(len(rpos))]
        for a in range(len(rpos)):
            color = col[a]
            if color == neutral or color == 0:
                continue
            for b in range(a + 1, len(rpos)):
                if col[b] != color:
                    continue
                if any(col[k] not in (neutral, 0) for k in range(a + 1, b)):
                    continue
                c0, c1 = cb[j]
                for cc in range(c0 + 1, c1):
                    if grid[rpos[a]][cc] != color or grid[rpos[b]][cc] != color:
                        continue
                    for k in range(a, b):
                        for y in range(rb[k][1] + 1, rb[k + 1][0]):
                            if grid[y][cc] == 0:
                                out[y][cc] = color
    return out
